function readStoredState(){
 // Une lo guardado en localStorage y sessionStorage: nunca se pierde un logro por haber leído solo una copia.
 const merged={done:{},excellent:{},xp:0};
 ['localStorage','sessionStorage'].forEach(name=>{try{const raw=window[name].getItem(STORE_KEY);if(!raw)return;const value=JSON.parse(raw);if(value&&typeof value==='object'&&!Array.isArray(value))mergeProgress(merged,value)}catch(e){}});
 return merged;
}
// Fusiona progreso sin borrar nunca nada: logros = unión, XP = el mayor, reto diario de hoy = completado si en alguna copia lo está.
function mergeProgress(target,source){
 if(!source||typeof source!=='object')return target;
 ['done','excellent'].forEach(key=>{
  if(!target[key]||typeof target[key]!=='object')target[key]={};
  const from=source[key];
  if(from&&typeof from==='object')Object.keys(from).forEach(k=>{if(from[k]&&!target[key][k])target[key][k]=from[k]});
 });
 target.xp=Math.max(Number(target.xp)||0,Number(source.xp)||0);
 if(source.daily&&typeof source.daily==='object'){
  if(!target.daily||(source.daily.date&&source.daily.date>target.daily.date)||(source.daily.date===target.daily.date&&source.daily.done))target.daily=Object.assign({},source.daily);
 }
 target._savedAt=Math.max(Number(target._savedAt)||0,Number(source._savedAt)||0);
 return target;
}
let state=readStoredState();state.done=state.done&&typeof state.done==='object'?state.done:{};state.excellent=state.excellent&&typeof state.excellent==='object'?state.excellent:{};state.xp=Number(state.xp)||0;
window.addEventListener('pagehide',save);
let run=null;
const $=id=>document.getElementById(id);
function save(){
 // Antes de escribir, fusiona con lo ya guardado: una pestaña o copia antigua ya no puede borrar el avance de otra.
 ['localStorage','sessionStorage'].forEach(name=>{try{const raw=window[name].getItem(STORE_KEY);if(raw)mergeProgress(state,JSON.parse(raw))}catch(e){}});
 state._savedAt=Date.now();const raw=JSON.stringify(state);let saved=false;
 try{localStorage.setItem(STORE_KEY,raw);saved=true}catch(e){}
 try{sessionStorage.setItem(STORE_KEY,raw);saved=true}catch(e){}
 try{schedulePush()}catch(e){}
 return saved;
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){save();pushServer()}});
try{if(navigator.storage&&navigator.storage.persist)navigator.storage.persist()}catch(e){}
/* LR_SERVER_SYNC_V1: copia del avance en el servidor (sobrevive a cambios de navegador/dispositivo). Sin servidor, no hace nada. */
let srvTimer=0,srvOk=true;
const CODE_KEY='alodeutsch_lernreise_code_v1';
function validCode(c){return /^[A-Z0-9]{12}$/.test(c||'')}
function getCode(){
 let c='';try{c=localStorage.getItem(CODE_KEY)||''}catch(e){}
 if(!validCode(c)){const al='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',r=new Uint8Array(12);try{crypto.getRandomValues(r)}catch(e){for(let i=0;i<12;i++)r[i]=Math.floor(Math.random()*256)}c=Array.from(r,x=>al[x%al.length]).join('');try{localStorage.setItem(CODE_KEY,c)}catch(e){}}
 return c;
}
function serverUrl(){return '/api/lernreise-progress?code='+encodeURIComponent(getCode())}
function pushServer(){
 if(!srvOk||!/^https?:/.test(location.protocol))return;
 try{fetch(serverUrl(),{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',keepalive:true,body:JSON.stringify({progress:state})}).then(r=>{if(r.status===404||r.status===405)srvOk=false}).catch(()=>{})}catch(e){}
}
function schedulePush(){clearTimeout(srvTimer);srvTimer=setTimeout(pushServer,1500)}
function pullServer(done){
 if(!/^https?:/.test(location.protocol)){if(done)done(false);return}
 try{fetch(serverUrl(),{credentials:'same-origin'}).then(r=>{if(!r.ok){if(r.status===404||r.status===405)srvOk=false;return null}return r.json()}).then(j=>{
  if(!j||!j.progress){if(done)done(false);return}
  mergeProgress(state,j.progress);save();pushServer();if(done)done(true);
 }).catch(()=>{if(done)done(false)})}catch(e){if(done)done(false)}
}
function codePanel(){
 if(!/^https?:/.test(location.protocol))return '';
 return '<section class="lr-world" style="--world-color:#7a5cc8"><div class="lr-world-head"><div class="lr-icon">🔑</div><div><small>COPIA DE SEGURIDAD</small><h3>Tu código de progreso</h3><p>Guárdalo: con él recuperas tu avance en otro navegador o dispositivo. Es personal; no se lo des a nadie.</p><p style="font-size:22px;font-weight:800;letter-spacing:3px;user-select:all">'+getCode()+'</p><button class="lr-timed-world" onclick="Lernreise.restoreCode()">Restaurar con otro código</button></div></div></section>';
}
function restoreCode(){
 const c=String(prompt(LR_X('Escribe tu código de progreso (12 letras/números):'),'')||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
 if(!c)return;if(!validCode(c)){alert(LR_X('El código debe tener 12 letras o números.'));return}
 try{localStorage.setItem(CODE_KEY,c)}catch(e){}
 pullServer(ok=>{renderMap();alert(LR_X(ok?'Avance restaurado.':'No se pudo conectar con el servidor.'))});
}

