function addSentenceOrderChallenges(){
 worlds.forEach((w)=>w.missions.forEach((m,mi)=>{
  if(mi%3!==1||m.qs.some(q=>q[5]==='order'))return;
  let sentence='';
  for(const q of m.qs){
   if((q[5]==='listen'||q[5]==='speak')&&typeof q[6]==='string'&&q[6].trim().split(/\s+/).length>=3){sentence=q[6].trim();break}
   if(Array.isArray(q[1])&&typeof q[1][q[2]]==='string'&&q[1][q[2]].trim().split(/\s+/).length>=3&&/[.!?]$/.test(q[1][q[2]].trim())){sentence=q[1][q[2]].trim();break}
  }
  if(sentence)m.qs.push(['🧩 Ordna las palabras para reconstruir la frase alemana.',[],0,'Frase correcta: '+sentence,'Busca primero el verbo conjugado. En una oración principal suele ir en segunda posición; en una subordinada va al final.','order',sentence]);
 }));
}
addSentenceOrderChallenges();
function renderMap(){
 const total=worlds.reduce((n,w)=>n+w.missions.length,0);
 const done=Object.keys(state.done).filter(k=>state.done[k]).length;
 const excellent=Object.keys(state.excellent).filter(k=>state.excellent[k]).length;
 $('lr-overall').style.width=(excellent/total*100)+'%';
 $('lr-total').textContent=excellent+' / '+total+' estrellas · ⭐ '+state.xp+' XP';
 const daily=ensureDaily(),dailyCopy=$('lr-daily-copy'),dailyButton=$('lr-daily-button'),dailyFill=$('lr-daily-fill');if(dailyCopy)dailyCopy.textContent=daily.done?'¡Reto de hoy completado! Has ganado +15 XP. Vuelve mañana para otra aventura.':'Completa una misión hoy para ganar +15 XP extra.';if(dailyButton){dailyButton.textContent=daily.done?'¡Completado ✓':'¡Vamos!';dailyButton.disabled=!!daily.done;dailyButton.setAttribute('aria-label',daily.done?'Reto diario completado':'Empezar reto diario')}if(dailyFill)dailyFill.style.width=daily.done?'100%':'0%';
 $('lr-map').style.display='block';$('lr-play').style.display='none';
 $('lr-map').innerHTML=worlds.map((w,wi)=>{
  const count=w.missions.filter((m,mi)=>state.done[w.id+'-'+mi]).length;
  const gold=w.missions.filter((m,mi)=>state.excellent[w.id+'-'+mi]).length;
  const nodes=w.missions.map((m,mi)=>{
   const key=w.id+'-'+mi,d=!!state.done[key],e=!!state.excellent[key],u=unlocked(wi,mi);
   const symbol=e?'★':d?'✓':u?(mi===0?'🚩':'⭐'):'🔒';
   const status=e?'¡Excelente!':d?'Completada · puedes repetirla':u?'¡Te toca!':'Se abre al conseguir excelencia en este nivel';
   return '<div class="lr-node-wrap"><button class="lr-node '+(e?'excellent':d?'done':u?'active':'locked')+'" '+(!u?'disabled':'')+' aria-label="'+w.level+' '+m.title+'" onclick="Lernreise.start('+wi+','+mi+')"><span class="lr-node-orb">'+symbol+'</span><span class="lr-node-label">'+(mi+1)+'. '+m.title+'</span></button><div class="lr-node-info"><b>'+status+'</b><span>'+(e?'¡Ganaste tu estrella dorada!':d?'Vuelve a intentarlo para desbloquear el siguiente paso.':u?'Responde al menos el 70% para completar y el 90% para desbloquear todo el nivel.':'Consigue al menos un 90% en una misión de este nivel para abrirlas todas.')+'</span></div></div>';
  }).join('');
  return '<section class="lr-world" style="--world-color:'+w.color+'"><div class="lr-world-head"><div class="lr-icon">'+w.icon+'</div><div><small>'+w.level+' · MUNDO '+(wi+1)+'</small><h3>'+w.name+'</h3><p>'+w.desc+'</p><button class="lr-timed-world" onclick="Lernreise.timed('+wi+')">⚡ Contrarreloj · 18 s por pregunta</button></div></div><div class="lr-world-progress"><span>'+count+'/'+w.missions.length+' misiones</span><div class="track"><span style="width:'+(gold/w.missions.length*100)+'%"></span></div><span>⭐ '+gold+'</span></div><div class="lr-path">'+nodes+'</div>'+lrToolboxHTML(w.level)+'<div class="lr-world-foot">'+(gold===w.missions.length?'🏆 Welt gemeistert! ¡Has dominado este mundo!':gold===0?'🦉 Consejo: la primera misión está abierta. ¡Consigue excelencia para abrir el siguiente nodo!':'✨ Vas avanzando: '+gold+' estrella(s) de excelencia conseguidas.')+'</div></section>';
 }).join('')+codePanel();
}
function showPlay(html){$('lr-map').style.display='none';$('lr-play').style.display='block';$('lr-play').innerHTML=html}
function open(){addUI();LR_ENX();renderMap();if(typeof App!=='undefined'){if(typeof App.go==='function'){App.go('lernreise')}else if(typeof App.show==='function'){App.show('lernreise')}}}
function back(){if($('lr-play')&&$('lr-play').style.display!=='none'){renderMap();return}if(typeof App!=='undefined'&&App.goBack){App.goBack();return}if(typeof App!=='undefined'&&App.show){App.show('dashboard');return}/* Standalone route: return to the page that opened Lernreise instead of trapping the user on the map. */if(window.history&&window.history.length>1){window.history.back();return}window.location.href='./index.html'}
function start(w,m,timed){if(!unlocked(w,m))return;clearQuestionTimer();run={w,m,q:0,correct:0,answered:false,timed:!!timed,secondsLeft:18,timerId:null,orderSelected:[]};showQuestion()}
function timed(wi){const w=worlds[wi];if(!w)return;let mi=w.missions.findIndex((m,i)=>unlocked(wi,i)&&!state.done[w.id+'-'+i]);if(mi<0)mi=w.missions.findIndex((m,i)=>unlocked(wi,i));if(mi>=0)start(wi,mi,true)}
function clearQuestionTimer(){if(run&&run.timerId){clearInterval(run.timerId);run.timerId=null}}
function beginQuestionTimer(){clearQuestionTimer();if(!run||!run.timed)return;run.secondsLeft=18;const tick=()=>{const n=$('lr-timer-count'),fill=$('lr-timer-fill');if(n)n.textContent=run.secondsLeft+' s';if(fill)fill.style.width=(run.secondsLeft/18*100)+'%'};tick();run.timerId=setInterval(()=>{if(!run||run.answered){clearQuestionTimer();return}run.secondsLeft--;tick();if(run.secondsLeft<=0)timeExpired()},1000)}
function timeExpired(){if(!run||run.answered)return;clearQuestionTimer();run.answered=true;lernreiseTone('bad');document.querySelectorAll('#lr-play .lr-option,#lr-play .lr-order-word').forEach(b=>b.disabled=true);const f=$('lr-feedback');if(f){f.className='lr-feedback show bad';f.textContent='⏰ ¡Se acabó el tiempo! '+(worlds[run.w].missions[run.m].qs[run.q][3]||'Respira, revisa la explicación y vuelve a intentarlo.');lrEnableExplanation(true)}const nx=$('lr-next');if(nx){nx.disabled=false;nx.textContent=run.q===worlds[run.w].missions[run.m].qs.length-1?'Ver resultado →':'Siguiente →'}}
function showQuestion(){
 const w=worlds[run.w],m=w.missions[run.m],q=m.qs[run.q];run.answered=false;run.hinted=false;run.speechMatched=false;
 const mode=q[5]||'read',target=q[6]||q[0];run.orderSelected=[];
 const modeLabel=mode==='listen'?'🎧 HÖREN · Escucha y comprende':mode==='speak'?'🎙️ SPRECHEN · Habla en alemán':mode==='order'?'🧩 SATZ-LABYRINTH · Ordena la frase':run.timed?'⚡ ZEIT-CHALLENGE · Contrarreloj':'📚 LESEN · Lee y aprende';
 const timer=run.timed?'<div class="lr-timer-panel">⏳ Tiempo restante: <span id="lr-timer-count">18 s</span><div class="lr-timer-track"><span id="lr-timer-fill"></span></div></div>':'';
 let orderHtml='';if(mode==='order'){const words=String(target).trim().split(/\s+/).map((word,i)=>({word,i,sort:Math.sin((i+1)*17.13+run.m*5.7+run.q*2.4)})).sort((a,b)=>a.sort-b.sort);run.orderWords=words.map(x=>x.word);orderHtml='<div class="lr-order-board" aria-label="Palabras disponibles">'+words.map((x,i)=>'<button class="lr-order-word" id="lr-word-'+i+'" onclick="Lernreise.pickWord('+i+')">'+x.word+'</button>').join('')+'</div><div class="lr-order-answer" id="lr-order-answer"><span style="color:#7b7190">Toca las palabras en el orden correcto…</span></div><div class="lr-order-actions"><button class="lr-order-check" onclick="Lernreise.checkOrder()">Comprobar frase ✓</button><button class="lr-order-clear" onclick="Lernreise.clearOrder()">↺ Borrar</button></div>'}
 const listen=mode==='listen'?'<button class="lr-audio-btn" onclick="Lernreise.listen('+JSON.stringify(target).replace(/"/g,'&quot;')+')">🔊 Escuchar alemán</button>':'';
 const speak=mode==='speak'?'<div class="lr-speak-box"><button class="lr-audio-btn" onclick="Lernreise.listen('+JSON.stringify(target).replace(/"/g,'&quot;')+')">🔊 Escuchar modelo</button><button class="lr-audio-btn" id="lr-speak" onclick="Lernreise.speak()">🎙️ Hablar ahora</button><p id="lr-speech-status" class="lr-speech-status">Di la frase en voz alta. Si tu navegador no permite reconocer voz, podrás autoevaluarte.</p><button class="lr-self-check" onclick="Lernreise.selfCheck()">Ya la he dicho correctamente ✓</button></div>':'';
 showPlay('<div class="lr-game"><div class="lr-game-top"><div><div class="lr-qprogress">'+w.level+' · MISIÓN '+(run.m+1)+' · '+(run.q+1)+'/'+m.qs.length+(run.timed?' · ⚡ CONTRARRELOJ':'')+'</div><div class="lr-bar"><span style="width:'+(run.q/m.qs.length*100)+'%"></span></div></div><div class="lr-game-buddy">'+w.icon+'</div></div>'+timer+'<div class="lr-mode-label">'+modeLabel+'</div><h2>'+m.title+'</h2><p class="lr-question">'+q[0]+'</p>'+listen+speak+(mode==='speak'?'':mode==='order'?orderHtml:'<div class="lr-options">'+q[1].map((v,i)=>'<button class="lr-option" id="lr-o'+i+'" onclick="Lernreise.answer('+i+')">'+String.fromCharCode(65+i)+'. '+v+'</button>').join('')+'</div>')+'<button class="lr-hint-btn" onclick="Lernreise.hint()">💡 Dame una pista</button><div id="lr-hint" class="lr-hint"></div><div id="lr-feedback" class="lr-feedback"></div><button id="lr-reveal-answer" class="lr-reveal-btn" hidden onclick="Lernreise.revealAnswer()">✅ Mostrar respuesta correcta</button><div id="lr-answer-reveal" class="lr-answer-reveal" hidden></div><button id="lr-explain" class="lr-explain-btn" hidden onclick="Lernreise.explain()">📖 Ver explicación detallada</button><div id="lr-explanation-detail" class="lr-explanation-detail" hidden></div><button id="lr-next" class="lr-next" disabled onclick="Lernreise.next()">Comprobar respuesta →</button></div>');
 if(mode==='listen')setTimeout(()=>listenText(target),250);if(run.timed)beginQuestionTimer();
}
function listenText(text){try{if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(text));u.lang='de-CH';u.rate=.82;window.speechSynthesis.speak(u)}catch(e){}}
function listen(text){listenText(text)}
function speak(){
 if(!run||run.answered)return;
 const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;
 const status=$('lr-speech-status'),btn=$('lr-speak');
 if(!Speech){if(status)status.textContent='El reconocimiento de voz no está disponible en este navegador. Escucha el modelo y usa «Ya la he dicho correctamente» para continuar.';return}
 try{
  try{if('speechSynthesis' in window)window.speechSynthesis.cancel()}catch(e){}const rec=new Speech();rec.lang='de-CH';rec.interimResults=false;rec.maxAlternatives=3;
  if(btn){btn.disabled=true;btn.textContent='🎙️ Escuchando…'}
  if(status)status.textContent='Te escucho… Di la frase completa en alemán.';
  rec.onresult=function(ev){
   const heard=Array.from(ev.results[0]).map(x=>x.transcript).join(' ');
   const target=String(worlds[run.w].missions[run.m].qs[run.q][6]||'').toLowerCase().replace(/[.,!?«»]/g,'').trim();
   const clean=heard.toLowerCase().replace(/[.,!?«»]/g,'').trim();
   const compact=x=>x.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss').replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,' ').trim();
   const words=compact(target).split(' '),got=compact(clean).split(' ');
   const overlap=words.filter(x=>got.includes(x)).length/Math.max(1,words.length);
   run.speechMatched=compact(target)===compact(clean)||overlap>=.72;
   if(status)status.textContent=(run.speechMatched?'✅ ¡Bien dicho!':'🟡 Has dicho: «'+heard+'». Escucha el modelo e inténtalo otra vez o autoevalúate.');
   if(run.speechMatched){const self=$('lr-speak');if(self){self.textContent='✅ Voz reconocida';self.disabled=true}completeSpeaking(false)}
  };
  rec.onerror=function(){if(status)status.textContent='No se pudo reconocer la voz. Puedes intentarlo de nuevo o autoevaluarte.'};
  rec.onend=function(){const b=$('lr-speak');if(b&&!run.speechMatched){b.disabled=false;b.textContent='🎙️ Intentar otra vez'}};
  rec.start();
 }catch(e){if(status)status.textContent='No se pudo iniciar el micrófono. Revisa los permisos del navegador.';if(btn){btn.disabled=false;btn.textContent='🎙️ Hablar ahora'}}
}
function selfCheck(){if(!run||run.answered)return;run.speechMatched=true;const st=$('lr-speech-status');if(st)st.textContent='👍 Has registrado tu autoevaluación. Intenta pronunciar la frase sin mirar el modelo la próxima vez.';completeSpeaking(true)}
function completeSpeaking(selfRated){if(!run||run.answered)return;run.answered=true;run.correct++;lernreiseCelebrate('correct');const f=$('lr-feedback');if(f){f.className='lr-feedback show good';f.textContent=selfRated?'🎤 Práctica registrada. ¡Bien por intentarlo!':'🎉 ¡La frase ha sido reconocida! Buena pronunciación.'}const nx=$('lr-next');if(nx){nx.disabled=false;nx.textContent=run.q===worlds[run.w].missions[run.m].qs.length-1?'Ver resultado →':'Siguiente →'}lrEnableExplanation(false)}
function hint(){if(!run||run.answered)return;run.hinted=true;const q=worlds[run.w].missions[run.m].qs[run.q];const hintText=q[4]||'Lee la frase con atención. En alemán, el verbo conjugado suele ocupar la segunda posición en la oración principal y va al final en muchas subordinadas.';const el=$('lr-hint');if(el){el.textContent=hintText;el.classList.add('show')}}
function answer(i){if(!run||run.answered)return;clearQuestionTimer();const q=worlds[run.w].missions[run.m].qs[run.q];if(q[5]==='speak'&&!run.speechMatched){const st=$('lr-speech-status');if(st)st.textContent='Primero intenta decir la frase en voz alta o pulsa «Ya la he dicho correctamente».';return}run.answered=true;const ok=i===q[2];if(ok){run.correct++;lernreiseCelebrate('correct')}else{lernreiseTone('bad')}q[1].forEach((_,j)=>{const b=$('lr-o'+j);if(b){b.disabled=true;if(j===q[2])b.classList.add('good');else if(i===j)b.classList.add('bad')}});const f=$('lr-feedback');f.className='lr-feedback show '+(ok?'good':'bad');const praise=['🎉 ¡Correcto!','✨ ¡Sehr gut!','🦉 ¡Fantástico!','💜 ¡Lo has conseguido!'];const prefix=ok?praise[Math.floor(Math.random()*praise.length)]+' ':'💡 ¡Buen intento! ';f.textContent=prefix+q[3];lrEnableExplanation(!ok);const nx=$('lr-next');nx.disabled=false;nx.textContent=run.q===worlds[run.w].missions[run.m].qs.length-1?'Ver resultado →':'Siguiente →'}
function pickWord(i){if(!run||run.answered||!run.orderWords||!run.orderWords[i])return;run.orderSelected.push({i,word:run.orderWords[i]});const b=$('lr-word-'+i);if(b)b.disabled=true;renderOrderAnswer()}
function renderOrderAnswer(){const el=$('lr-order-answer');if(!el||!run)return;el.innerHTML=run.orderSelected.length?run.orderSelected.map((x,j)=>'<button class="lr-order-word" onclick="Lernreise.removeWord('+j+')">'+x.word+'</button>').join(''):'<span style="color:#7b7190">Toca las palabras en el orden correcto…</span>'}
function removeWord(j){if(!run||run.answered)return;const x=run.orderSelected.splice(j,1)[0];if(x){const b=$('lr-word-'+x.i);if(b)b.disabled=false}renderOrderAnswer()}
function clearOrder(){if(!run||run.answered)return;run.orderSelected=[];document.querySelectorAll('#lr-play .lr-order-word').forEach(b=>{if(b.id.startsWith('lr-word-'))b.disabled=false});renderOrderAnswer()}
function checkOrder(){if(!run||run.answered)return;const q=worlds[run.w].missions[run.m].qs[run.q];if(q[5]!=='order')return;if(run.orderSelected.length!==run.orderWords.length){const f=$('lr-feedback');if(f){f.className='lr-feedback show bad';f.textContent='Todavía faltan palabras. ¡Colócalas todas antes de comprobar!'}return}clearQuestionTimer();const answer=run.orderSelected.map(x=>x.word).join(' '),target=String(q[6]).trim();const ok=answer.replace(/[.,!?;:]+$/,'')===target.replace(/[.,!?;:]+$/,'');run.answered=true;if(ok){run.correct++;lernreiseCelebrate('correct')}else{lernreiseTone('bad')}document.querySelectorAll('#lr-play .lr-order-word').forEach(b=>b.disabled=true);const f=$('lr-feedback');if(f){f.className='lr-feedback show '+(ok?'good':'bad');f.textContent=(ok?'✨ ¡Frase perfecta! ':'💡 Casi. ')+(q[3]||('Modelo: '+target));lrEnableExplanation(!ok)}const nx=$('lr-next');if(nx){nx.disabled=false;nx.textContent=run.q===worlds[run.w].missions[run.m].qs.length-1?'Ver resultado →':'Siguiente →'}}
function next(){if(!run||!run.answered)return;if(run.q<worlds[run.w].missions[run.m].qs.length-1){run.q++;showQuestion();return}finish()}
function finish(){
 clearQuestionTimer();
 const w=worlds[run.w],mission=w.missions[run.m],key=w.id+'-'+run.m,total=mission.qs.length;
 const pct=Math.round(run.correct/total*100),needed=Math.ceil(total*.7),excellentNeeded=Math.ceil(total*.9);
 const passed=run.correct>=needed,excellent=run.correct>=excellentNeeded;
 const firstPass=passed&&!state.done[key],firstExcellent=excellent&&!state.excellent[key];
 if(passed)state.done[key]=true;
 if(excellent)state.excellent[key]=true;
 if(excellent)lernreiseCelebrate('excellent');else if(passed)lernreiseCelebrate('complete');
 if(firstPass)state.xp+=run.correct*10;
 if(firstExcellent)state.xp+=25;
 const daily=ensureDaily(),firstDaily=passed&&!daily.done;if(firstDaily){daily.done=true;state.xp+=15;}
 save();
 const widx=run.w,midx=run.m;
 const headline=excellent?'¡EXCELENTE!':passed?'¡Misión completada!':'¡Cada intento te enseña!';
 const sub=excellent?'¡Has ganado una estrella dorada y desbloqueado todas las misiones de este nivel!':passed?'Has completado la misión, pero necesitas un resultado excelente (90% o más) para desbloquear todas las misiones del nivel.':'Necesitas al menos '+needed+' respuestas correctas para completar la misión. ¡Repasa y vuelve a probar!';
 showPlay('<div class="lr-result"><div class="emoji">'+(excellent?'🏆':passed?'🌱':'🦉')+'</div><h2>'+headline+'</h2><p>Resultado: <b>'+run.correct+'/'+total+' ('+pct+'%)</b></p><p>'+sub+'</p>'+(excellent?'<div class="lr-sticker">⭐ ESTRELLA DE EXCELENCIA +25 XP</div>':'')+'<p>⭐ XP de esta partida: '+((firstPass?run.correct*10:0)+(firstExcellent?25:0)+(firstDaily?15:0))+'</p>'+(firstDaily?'<div class="lr-sticker">🎯 RETO DIARIO COMPLETADO +15 XP</div>':'')+'<button class="lr-next" onclick="Lernreise.map()">Volver al camino 🗺️</button></div>');
 renderMap();$('lr-map').style.display='none';$('lr-play').style.display='block';
 if(excellent){let nw=widx,nm=midx+1;if(nm>=w.missions.length){nw++;nm=0}if(nw<worlds.length&&unlocked(nw,nm))$('lr-play').querySelector('.lr-result').insertAdjacentHTML('beforeend','<button class="lr-secondary" onclick="Lernreise.start('+nw+','+nm+')">¡Seguir el camino! →</button>')}
}
function map(){renderMap()}
function daily(){startDaily()}
function revealAnswer(){lrRevealAnswer()}function explain(){lrExplain()}
function hideExplanation(){lrHideExplanation()}

