function lrT(s){if(typeof s!=='string')return s;const D=LR_EN_DATA.D,U=LR_EN_DATA.UI;if(D[s]!==undefined)return D[s];if(U[s]!==undefined)return U[s];
 const t=s.trim();if(t!==s){const r=D[t]!==undefined?D[t]:U[t];if(r!==undefined){const a=s.match(/^\s*/)[0],b=s.match(/\s*$/)[0];return a+r+b}}
 for(const p of LR_EN_DATA.PRE){if(s.startsWith(p[0]))return p[1]+lrT(s.slice(p[0].length))}
 let m=null;if(/MISIÓN|MUNDO|\d+ misiones/.test(s))return s.replace(/MISIÓN/g,'MISSION').replace(/MUNDO/g,'WORLD').replace(/misiones/g,'missions');
 m=s.match(/^(\d+) misiones$/);if(m)return m[1]+' missions';
 m=s.match(/^ ?misiones$/);if(m)return ' missions';
 m=s.match(/^Lección (\d+): (.*)$/);if(m)return 'Lesson '+m[1]+': '+m[2];
 let r=s;for(const p of (LR_EN_DATA.SUB||[])){if(r.indexOf(p[0])>=0)r=r.split(p[0]).join(p[1])}
 return r}
function lrDeep(o){if(Array.isArray(o)){for(let i=0;i<o.length;i++){const v=o[i];if(typeof v==='string')o[i]=lrT(v);else if(v&&typeof v==='object')lrDeep(v)}}
 else if(o&&typeof o==='object'){for(const k in o){if(k==='id'||k==='color'||k==='icon'||k==='level')continue;const v=o[k];if(typeof v==='string')o[k]=lrT(v);else if(v&&typeof v==='object')lrDeep(v)}}}
function lrDomTr(root){if(!root)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(n){const p=n.parentNode&&n.parentNode.nodeName;return(p==='SCRIPT'||p==='STYLE')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});
 const nodes=[];while(w.nextNode())nodes.push(w.currentNode);nodes.forEach(n=>{const v=lrT(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v});
 if(root.querySelectorAll)root.querySelectorAll('[placeholder],[title],[aria-label]').forEach(e=>{['placeholder','title','aria-label'].forEach(a=>{const x=e.getAttribute(a);if(x){const y=lrT(x);if(y!==x)e.setAttribute(a,y)}})})}
