if(LR_IS_EN){LR_ENX();const startObs=()=>{lrDomTr(document.body);let busy=false;new MutationObserver(ms=>{if(busy)return;busy=true;try{ms.forEach(m=>{m.addedNodes.forEach(n=>{if(n.nodeType===1)lrDomTr(n);else if(n.nodeType===3){const v=lrT(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v}});if(m.type==='characterData'){const v=lrT(m.target.nodeValue);if(v!==m.target.nodeValue)m.target.nodeValue=v}})}finally{busy=false}}).observe(document.body,{childList:true,subtree:true,characterData:true})};
 if(document.body)startObs();else document.addEventListener('DOMContentLoaded',startObs)}

